// Greatest-N-per-group: wrong global LIMIT vs ROW_NUMBER vs DENSE_RANK.
package com.bank.topn;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;
import java.util.stream.*;

public class TopNDemo {
    private static final Logger log = Logger.getLogger(TopNDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TxnRepository repo = new TxnRepository();
        TopNService service = new TopNService(repo);

        log.info("=== WRONG: global ORDER BY amount DESC LIMIT 2 ===");
        service.globalTop2().forEach(t -> log.warning(() ->
            t.txnId + " " + t.accountId + " Rs." + t.amount + " (all from one account!)"));

        log.info("=== CORRECT: ROW_NUMBER top-2 per account (exactly 2 each) ===");
        service.top2PerAccountRowNumber().forEach(t -> log.info(() ->
            t.txnId + " " + t.accountId + " Rs." + t.amount));

        log.info("=== DENSE_RANK top-2 distinct amounts per account (ties included) ===");
        service.top2PerAccountDenseRank().forEach(t -> log.info(() ->
            t.txnId + " " + t.accountId + " Rs." + t.amount));
    }
}

// ─── Would be in model/Txn.java ───
class Txn {
    final String txnId, accountId; final BigDecimal amount;
    Txn(String id, String acct, BigDecimal amt) {
            this.txnId = id;
            this.accountId = acct
            this.amount = amt;
    }
}

// ─── Would be in repository/TxnRepository.java ───
class TxnRepository {
    List<Txn> findAll() {
        return List.of(
            new Txn("T1", "SAV2001", new BigDecimal("90000")),
            new Txn("T2", "SAV2001", new BigDecimal("80000")),
            new Txn("T3", "SAV2001", new BigDecimal("10000")),
            new Txn("T4", "CUR3001", new BigDecimal("50000")),
            new Txn("T5", "CUR3001", new BigDecimal("50000")), // tie
            new Txn("T6", "CUR3001", new BigDecimal("20000")));
    }
}

// ─── Would be in service/TopNService.java ───
class TopNService {
    private final TxnRepository repo;
    TopNService(TxnRepository repo) { this.repo = repo; }

    // WRONG: sorts the whole table, keeps 2 overall (global top-N).
    List<Txn> globalTop2() {
        return repo.findAll().stream()
            .sorted((a, b) -> b.amount.compareTo(a.amount))
            .limit(2).toList();
    }

    // CORRECT: ROW_NUMBER per account — exactly 2 rows each, deterministic tie-break.
    List<Txn> top2PerAccountRowNumber() {
        Map<String, List<Txn>> byAccount = repo.findAll().stream()
            .collect(Collectors.groupingBy(t -> t.accountId, LinkedHashMap::new, Collectors.toList()));
        List<Txn> out = new ArrayList<>();
        byAccount.values().forEach(list -> {
            list.stream()
                // ORDER BY amount DESC, txn_id DESC (tie-breaker makes ROW_NUMBER deterministic)
                .sorted(Comparator.comparing((Txn t) -> t.amount).reversed()
                        .thenComparing(t -> t.txnId, Comparator.reverseOrder()))
                .limit(2)                      // rn <= 2
                .forEach(out::add);
        });
        return out;
    }

    // DENSE_RANK per account — top 2 distinct amounts, ties at a level both kept.
    List<Txn> top2PerAccountDenseRank() {
        Map<String, List<Txn>> byAccount = repo.findAll().stream()
            .collect(Collectors.groupingBy(t -> t.accountId, LinkedHashMap::new, Collectors.toList()));
        List<Txn> out = new ArrayList<>();
        byAccount.values().forEach(list -> {
            // distinct amounts sorted desc; keep top 2 amount levels
            List<BigDecimal> topAmounts = list.stream().map(t -> t.amount)
                .distinct().sorted(Comparator.reverseOrder()).limit(2).toList();
            list.stream().filter(t -> topAmounts.contains(t.amount)).forEach(out::add);
        });
        return out;
    }
}

